-- =====================================================================
-- 5. RISK-MATH REALIGNMENT
--    Re-derives prob / sev / inherit / residual / actionType for every
--    seeded asset using the cybersecurity-grade engine (NIST SP 800-30,
--    ISO 27005/27001:2022, CIS v8, SOC 2 TSC, PCI-DSS v4.0, RA 10173).
--    Mirrors CONTROL_WEIGHTS / CONTROL_SYNERGIES / MANDATORY_CONTROLS in
--    assets/scripts/app.js. Idempotent — safe to re-run.
-- =====================================================================

CREATE OR REPLACE FUNCTION public.il_inherit(s int, p int)
RETURNS text
LANGUAGE sql IMMUTABLE AS $func$
  SELECT CASE s::text || '-' || p::text
    WHEN '5-1' THEN 'Moderate' WHEN '5-2' THEN 'Moderate' WHEN '5-3' THEN 'High'
    WHEN '5-4' THEN 'High'     WHEN '5-5' THEN 'High'
    WHEN '4-1' THEN 'Low'      WHEN '4-2' THEN 'Moderate' WHEN '4-3' THEN 'Moderate'
    WHEN '4-4' THEN 'High'     WHEN '4-5' THEN 'High'
    WHEN '3-1' THEN 'Low'      WHEN '3-2' THEN 'Moderate' WHEN '3-3' THEN 'Moderate'
    WHEN '3-4' THEN 'Moderate' WHEN '3-5' THEN 'High'
    WHEN '2-1' THEN 'Low'      WHEN '2-2' THEN 'Low'      WHEN '2-3' THEN 'Moderate'
    WHEN '2-4' THEN 'Moderate' WHEN '2-5' THEN 'Moderate'
    WHEN '1-1' THEN 'Very Low' WHEN '1-2' THEN 'Low'      WHEN '1-3' THEN 'Low'
    WHEN '1-4' THEN 'Low'      WHEN '1-5' THEN 'Moderate'
    ELSE 'Moderate'
  END;
$func$;

-- Step 1: Sync roll-up columns from worst paired scenario in asset_risks_json.
-- Do NOT mandatory-floor recompute here — incomplete AssetControls would inflate
-- every asset to Moderate/High. The app uses JSON roll-up for dashboard/register KPIs.
WITH worst AS (
  SELECT
    a.id,
    (
      SELECT elem
      FROM jsonb_array_elements(a.asset_risks_json::jsonb) AS elem
      ORDER BY
        CASE elem->>'residual'
          WHEN 'High' THEN 3 WHEN 'Moderate' THEN 2 WHEN 'Low' THEN 1 WHEN 'Very Low' THEN 0 ELSE 0
        END DESC,
        CASE elem->>'inherit'
          WHEN 'High' THEN 3 WHEN 'Moderate' THEN 2 WHEN 'Low' THEN 1 WHEN 'Very Low' THEN 0 ELSE 0
        END DESC
      LIMIT 1
    ) AS sc
  FROM public."Assets" a
  WHERE a.asset_risks_json IS NOT NULL
    AND trim(a.asset_risks_json) <> ''
    AND a.asset_risks_json <> 'null'
)
UPDATE public."Assets" a SET
  prob     = COALESCE((w.sc->>'prob')::int, a.prob),
  sev      = COALESCE((w.sc->>'sev')::int, a.sev),
  inherit  = COALESCE(w.sc->>'inherit', a.inherit),
  residual = COALESCE(w.sc->>'residual', a.residual)
FROM worst w
WHERE a.id = w.id AND w.sc IS NOT NULL;

-- Step 2: Cap residual to inherent when roll-up exceeds inherent (no open control gap in seed)
UPDATE public."Assets" SET residual = inherit
WHERE (
  CASE residual WHEN 'High' THEN 3 WHEN 'Moderate' THEN 2 WHEN 'Low' THEN 1 ELSE 0 END
) > (
  CASE inherit WHEN 'High' THEN 3 WHEN 'Moderate' THEN 2 WHEN 'Low' THEN 1 ELSE 0 END
);

-- Step 3: Risk-appetite enforcement on actionType
UPDATE public."Assets" SET "actionType" = 'Mitigate'
WHERE "actionType" = 'Accept'
  AND ( residual = 'High'
     OR (type = 'FA' AND residual NOT IN ('Low', 'Very Low'))
     OR ("ciaScore" >= 8 AND residual = 'Moderate') );

